 void Line(double x,double y,double X,double Y,string layer="DF_CONTORNO",bool paper=false){Add(new Line(P(x,y),P(X,Y)),layer,paper);}
 ObjectId Poly(double[] xy,string layer="DF_CONTORNO",bool closed=false,bool paper=false){var p=new Polyline();for(int i=0;i<xy.Length;i+=2)p.AddVertexAt(i/2,new Point2d(xy[i],xy[i+1]),0,0,0);p.Closed=closed;return Add(p,layer,paper);}
